const struct cc_vc4_profile_data *cc_vc4_profile_data(enum cc_vc4_profile profile)
{
    for (size_t i = 0; i < sizeof(profiles) / sizeof(profiles[0]); ++i)
        if (profiles[i].info.profile == profile)
            return &profiles[i];
    return NULL;
}
